package com.ke.ticketsystemke.service;
import com.ke.ticketsystemke.dto.*; import com.ke.ticketsystemke.entity.*; import com.ke.ticketsystemke.repository.*;
import org.springframework.dao.DataIntegrityViolationException; import org.springframework.http.*; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import org.springframework.web.server.ResponseStatusException;
import java.time.*; import java.util.*;
@Service
public class WarrantyReplacementService {
 public static final String MOVE_READY=WarrantyResolutionService.MOVE_READY; private static final ZoneId ZONE=ZoneId.of("Asia/Kolkata");
 private final TicketRepository tickets;private final WarrantyClaimRepository claims;private final WarrantyReplacementRepository replacements;private final AccessService access;private final WarrantyClaimEventService audit;private final WarrantyClaimService claimService;private final GenericTransitionExecutorService transitionValidator;private final WorkflowTransitionExecutionService transitionExecutor;
 public WarrantyReplacementService(TicketRepository tickets,WarrantyClaimRepository claims,WarrantyReplacementRepository replacements,AccessService access,WarrantyClaimEventService audit,WarrantyClaimService claimService,GenericTransitionExecutorService transitionValidator,WorkflowTransitionExecutionService transitionExecutor){this.tickets=tickets;this.claims=claims;this.replacements=replacements;this.access=access;this.audit=audit;this.claimService=claimService;this.transitionValidator=transitionValidator;this.transitionExecutor=transitionExecutor;}
 @Transactional(readOnly=true) public List<WarrantyReplacementResponse> list(Long ticketId,Long claimId,String actor){view(actor);context(ticketId,claimId,null,actor,false);return replacements.findByWarrantyClaim_IdOrderByReplacementSequenceDesc(claimId).stream().map(WarrantyReplacementResponse::from).toList();}
 @Transactional public WarrantyClaimResponse create(Long ticketId,Long claimId,ReplacementDetailsRequest r,String actor){Context x=context(ticketId,claimId,r.claimVersion(),actor,true);WarrantyClaim c=x.claim();if(c.getState()!=WarrantyClaimState.REPLACEMENT_APPROVED_AWAITING_PRODUCT||c.getResult()!=WarrantyClaimResult.PENDING)conflict("Warranty claim is not awaiting an approved replacement");if(replacements.existsByWarrantyClaim_IdAndActiveTrue(claimId))conflict("An active replacement already exists");WarrantyReplacement n=new WarrantyReplacement();n.setWarrantyClaim(c);n.setReplacementSequence(replacements.findMaxSequence(claimId)+1);n.setCreatedByEmployeeId(actor);apply(n,r,true);saveNew(n);completeReceived(c,actor);audit.record(c,WarrantyClaimEventType.WARRANTY_REPLACEMENT_RECEIVED,actor,"Replacement product received",metadata(n));return claimService.response(c,x.ticket());}
 @Transactional public WarrantyClaimResponse update(Long ticketId,Long claimId,Long replacementId,ReplacementDetailsRequest r,String actor){Context x=context(ticketId,claimId,r.claimVersion(),actor,true);WarrantyReplacement n=active(claimId,replacementId);version(n,r.replacementVersion());if(x.claim().getState()==WarrantyClaimState.CLOSED)conflict("Closed replacement records are read-only");if(materialChanged(n,r))conflict("Product, model, serial, and reference corrections must supersede the active replacement");Map<String,Object> before=metadata(n);apply(n,r,false);n.setUpdatedByEmployeeId(actor);replacements.saveAndFlush(n);audit.record(x.claim(),WarrantyClaimEventType.WARRANTY_REPLACEMENT_DETAILS_UPDATED,actor,"Replacement details updated",Map.of("replacementSequence",n.getReplacementSequence(),"before",before,"after",metadata(n)));return claimService.response(x.claim(),x.ticket());}
 @Transactional public WarrantyClaimResponse supersede(Long ticketId,Long claimId,Long replacementId,SupersedeWarrantyReplacementRequest r,String actor){Context x=context(ticketId,claimId,r.claimVersion(),actor,true);WarrantyReplacement old=active(claimId,replacementId);version(old,r.currentReplacementVersion());if(x.claim().getState()==WarrantyClaimState.CLOSED)conflict("Closed replacement records are read-only");old.setActive(false);old.setSupersedeReason(trim(r.supersedeReason()));old.setUpdatedByEmployeeId(actor);replacements.saveAndFlush(old);WarrantyReplacement n=new WarrantyReplacement();n.setWarrantyClaim(x.claim());n.setReplacementSequence(replacements.findMaxSequence(claimId)+1);n.setCreatedByEmployeeId(actor);apply(n,r.replacement(),true);saveNew(n);completeReceived(x.claim(),actor);Map<String,Object> meta=new LinkedHashMap<>();meta.put("oldReplacementId",old.getId());meta.put("oldSequence",old.getReplacementSequence());meta.put("newReplacementId",n.getId());meta.put("newSequence",n.getReplacementSequence());meta.put("reason",trim(r.supersedeReason()));meta.put("previousSerial",safe(old.getNewSerialNumber()));meta.put("newSerial",safe(n.getNewSerialNumber()));audit.record(x.claim(),WarrantyClaimEventType.WARRANTY_REPLACEMENT_SUPERSEDED,actor,"Replacement record superseded",meta);return claimService.response(x.claim(),x.ticket());}
 @Transactional public WarrantyResolutionResponse moveReady(Long ticketId,Long claimId,WarrantyVersionRequest r,String actor){Context x=context(ticketId,claimId,r.version(),actor,true);WarrantyReplacement n=replacements.findByWarrantyClaim_IdAndActiveTrue(claimId).orElseThrow(()->new ResponseStatusException(HttpStatus.CONFLICT,"An active replacement is required"));if(x.claim().getResult()!=WarrantyClaimResult.REPLACEMENT_DONE||!identityComplete(n))conflict("Complete replacement serial and reference details before Ready Delivery");if(x.claim().getState()!=WarrantyClaimState.REPLACEMENT_RECEIVED)conflict("Replacement is not ready for delivery workflow");TicketResponse tr=execute(x.ticket(),actor);x.claim().setState(WarrantyClaimState.DELIVERY_PENDING);saveClaim(x.claim(),actor);audit.record(x.claim(),WarrantyClaimEventType.WARRANTY_REPLACEMENT_READY_FOR_DELIVERY,actor,"Replacement ticket moved toward Ready Delivery",Map.of("replacementSequence",n.getReplacementSequence(),"workflowAction",MOVE_READY,"ticketStatus",safe(tr.statusKey())));return new WarrantyResolutionResponse(claimService.response(x.claim(),x.ticket()),tr,"Replacement ready for delivery");}
 @Transactional public WarrantyClaimResponse delivered(Long ticketId,Long claimId,ReplacementDeliveredRequest r,String actor){Context x=context(ticketId,claimId,r.claimVersion(),actor,true);WarrantyReplacement n=replacements.findByWarrantyClaim_IdAndActiveTrue(claimId).orElseThrow(()->new ResponseStatusException(HttpStatus.CONFLICT,"An active replacement is required"));version(n,r.replacementVersion());if(!deliveredStatus(x.ticket()))conflict("The ticket must first be delivered through the ticket delivery workflow");if(r.deliveredDate().isAfter(LocalDate.now(ZONE))||r.deliveredDate().isBefore(n.getReplacementReceivedDate()))bad("Replacement delivery date must be between received date and today");n.setReplacementGivenToCustomerDate(r.deliveredDate());n.setUpdatedByEmployeeId(actor);replacements.saveAndFlush(n);WarrantyClaim c=x.claim();c.setResult(WarrantyClaimResult.REPLACEMENT_DONE);c.setState(WarrantyClaimState.CLOSED);c.setActive(false);c.setResolvedAt(Instant.now());c.setClaimClosedAt(Instant.now());c.setClaimClosedByEmployeeId(actor);saveClaim(c,actor);audit.record(c,WarrantyClaimEventType.WARRANTY_REPLACEMENT_GIVEN_TO_CUSTOMER,actor,"Replacement given to customer",Map.of("replacementSequence",n.getReplacementSequence(),"deliveryDate",r.deliveredDate()));audit.record(c,WarrantyClaimEventType.WARRANTY_REPLACEMENT_CLAIM_CLOSED,actor,"Replacement warranty claim closed",Map.of("replacementSequence",n.getReplacementSequence()));return claimService.response(c,x.ticket());}
 private void apply(WarrantyReplacement n,ReplacementDetailsRequest r,boolean identity){if(r.replacementReceivedDate().isAfter(LocalDate.now(ZONE)))bad("Replacement received date cannot be in the future");String product=trim(r.newProductName()),type=trim(r.newProductType()),serial=trim(r.newSerialNumber()),reference=trim(r.replacementReferenceNumber());if(product==null&&type==null)bad("New product name or product type is required");if(serial==null&&trim(r.serialNumberOverrideReason())==null)bad("New serial number or a manager override reason is required");if(reference==null&&trim(r.referenceOverrideReason())==null)bad("Replacement reference number or an override reason is required");if(r.newWarrantyStartDate()!=null&&r.newWarrantyEndDate()!=null&&r.newWarrantyEndDate().isBefore(r.newWarrantyStartDate()))bad("New warranty end date cannot be before start date");n.setReplacementReceivedDate(r.replacementReceivedDate());n.setNewProductName(product);n.setNewProductType(type);n.setNewModelNumber(trim(r.newModelNumber()));n.setNewSerialNumber(serial);n.setNormalizedNewSerialNumber(normalize(serial));n.setNewWarrantyStartDate(r.newWarrantyStartDate());n.setNewWarrantyEndDate(r.newWarrantyEndDate());n.setReplacementReferenceNumber(reference);n.setNormalizedReferenceNumber(normalize(reference));n.setReplacementProvidedBy(trim(r.replacementProvidedBy()));n.setReplacementNotes(trim(r.replacementNotes()));n.setSerialNumberOverrideReason(serial==null?trim(r.serialNumberOverrideReason()):null);n.setReferenceOverrideReason(reference==null?trim(r.referenceOverrideReason()):null);}
 private boolean materialChanged(WarrantyReplacement n,ReplacementDetailsRequest r){return !Objects.equals(n.getNewProductName(),trim(r.newProductName()))||!Objects.equals(n.getNewProductType(),trim(r.newProductType()))||!Objects.equals(n.getNewModelNumber(),trim(r.newModelNumber()))||!Objects.equals(n.getNewSerialNumber(),trim(r.newSerialNumber()))||!Objects.equals(n.getReplacementReferenceNumber(),trim(r.replacementReferenceNumber()));}
 private void completeReceived(WarrantyClaim c,String actor){c.setResult(WarrantyClaimResult.REPLACEMENT_DONE);c.setState(WarrantyClaimState.REPLACEMENT_RECEIVED);c.setNextFollowUpDate(null);c.setFollowUpNotes(null);c.setFollowUpSource(null);saveClaim(c,actor);}
 private void saveNew(WarrantyReplacement n){n.setUpdatedByEmployeeId(n.getCreatedByEmployeeId());try{replacements.saveAndFlush(n);}catch(DataIntegrityViolationException e){conflict("An active replacement already exists or replacement data is invalid");}}
 private Context context(Long ticketId,Long claimId,Long claimVersion,String actor,boolean resolve){if(resolve){access.requireAllowed(actor,AccessKey.VIEW_TICKETS);access.requireAllowed(actor,AccessKey.RESOLVE_WARRANTY);}else view(actor);Ticket t=tickets.findById(ticketId).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Ticket not found"));WarrantyClaim c=claims.findById(claimId).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Warranty claim not found"));if(!Objects.equals(c.getTicket().getId(),ticketId))throw new ResponseStatusException(HttpStatus.NOT_FOUND,"Warranty claim not found");if(resolve&&!c.isActive())conflict("Inactive warranty claims are read-only");if(claimVersion!=null&&!Objects.equals(c.getVersion(),claimVersion))conflict("Warranty claim was updated by another user");return new Context(t,c);}
 private WarrantyReplacement active(Long claimId,Long id){WarrantyReplacement n=replacements.findById(id).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Replacement not found"));if(!Objects.equals(n.getWarrantyClaim().getId(),claimId))throw new ResponseStatusException(HttpStatus.NOT_FOUND,"Replacement not found");if(!n.isActive())conflict("Superseded replacements are read-only");return n;} private void version(WarrantyReplacement n,Long v){if(v==null||!Objects.equals(n.getVersion(),v))conflict("Replacement was updated by another user");}
 private TicketResponse execute(Ticket t,String actor){try{var p=transitionValidator.prepareActionExecution(t.getId(),MOVE_READY,actor);GenericTransitionExecutionRequest q=new GenericTransitionExecutionRequest();q.setReason("Replacement received and ready for customer delivery");return transitionExecutor.execute(p,actor,q);}catch(ResponseStatusException e){if(e.getStatusCode()==HttpStatus.FORBIDDEN)throw e;throw new ResponseStatusException(HttpStatus.CONFLICT,"Replacement Ready Delivery workflow is missing or ambiguous");}}
 private boolean deliveredStatus(Ticket t){WorkflowStatus s=t.getStatusRecord();if(s==null)return t.getStatus()==TicketStatus.COMPLETED;String k=s.getStatusKey()==null?"":s.getStatusKey().toUpperCase(Locale.ROOT);return s.isTerminal()&&s.getBehaviorBucket()==TicketStatus.COMPLETED&&k.contains("DELIVER");}
 private boolean identityComplete(WarrantyReplacement n){return trim(n.getNewSerialNumber())!=null&&trim(n.getReplacementReferenceNumber())!=null&&(trim(n.getNewProductName())!=null||trim(n.getNewProductType())!=null);} private void saveClaim(WarrantyClaim c,String actor){c.setUpdatedByEmployeeId(actor);claims.saveAndFlush(c);} private void view(String a){access.requireAllowed(a,AccessKey.VIEW_TICKETS);access.requireAllowed(a,AccessKey.VIEW_WARRANTY);} private Map<String,Object> metadata(WarrantyReplacement n){Map<String,Object> m=new LinkedHashMap<>();m.put("replacementSequence",n.getReplacementSequence());m.put("product",safe(n.getNewProductName()!=null?n.getNewProductName():n.getNewProductType()));m.put("model",safe(n.getNewModelNumber()));m.put("serial",safe(n.getNewSerialNumber()));m.put("reference",safe(n.getReplacementReferenceNumber()));m.put("receivedDate",n.getReplacementReceivedDate());m.put("serialOverride",n.getNewSerialNumber()==null);return m;} private String normalize(String s){String v=trim(s);return v==null?null:v.toUpperCase(Locale.ROOT).replaceAll("[^A-Z0-9]","");} private String trim(String s){return s==null||s.trim().isEmpty()?null:s.trim();}private Object safe(Object v){return v==null?"":v;}private void bad(String m){throw new ResponseStatusException(HttpStatus.BAD_REQUEST,m);}private void conflict(String m){throw new ResponseStatusException(HttpStatus.CONFLICT,m);} private record Context(Ticket ticket,WarrantyClaim claim){}
}
